/// Kontakt's Versatile knob laws (docs/re/engine/filt-multi-versatile.md),
/// as the Kontakt translator applies them.
fn versatile(cut: f32, res: [f32; 3]) -> CascadeSettings {
    let hz = 440.0
        * ((cut * 111.0 + 20.0 - 69.0) / 12.0).exp2()
        * (f64::from_bits(0x4019_21ca_c083_126f) / std::f64::consts::TAU) as f32;
    let stage = |r: f32| {
        let q = if r > 0.5 {
            (r - 0.5) * 0.66 + 0.65
        } else {
            r * 1.3
        };
        CascadeStage {
            q,
            limit: (q + 1.3075) * q * 0.293 + 0.7352,
            peak: 1.0 / ((1.0 - r) * 1.4 + 0.05),
            morph: 0.0,
            wet: 1.0,
        }
    };
    CascadeSettings {
        hz,
        shifts: [0.0; 2],
        stages: res.map(stage),
        gain: 1.0,
    }
}

#[test]
fn versatile_matches_the_native_code() {
    let mut failures = Vec::new();
    for (cut, res, impulse, native) in NATIVE {
        let mut c = Cascade::new(versatile(cut, res), 48_000);
        let ours: Vec<f32> = (0..64)
            .map(|i| {
                let x = if impulse {
                    f32::from(u8::from(i == 0))
                } else if (i / 20) % 2 == 0 {
                    4.0
                } else {
                    -4.0
                };
                let mut io = [[x, x]];
                c.process(&mut io);
                io[0][0]
            })
            .collect();
        let scale = native.iter().fold(1e-3f32, |m, v| m.max(v.abs()));
        let err = ours
            .iter()
            .zip(&native)
            .map(|(a, b)| (a - b).abs() / scale)
            .fold(0.0, f32::max);
        if err >= 2e-5 {
            failures.push(format!("cut {cut} res {res:?} impulse {impulse}: {err}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// A cutoff jump glides on the clock: through a 1 kHz sine, the output's
/// curvature (second difference) never spikes above what the settled sine
/// has, as an instant jump of the state's gains would make it; and the corner
/// lands on the new setting.
#[test]
fn a_cutoff_jump_glides_without_a_step() {
    let mut c = Cascade::new(versatile(0.2, [0.0; 3]), 48_000);
    let sine = |n: usize| (n as f32 * std::f32::consts::TAU * 1000.0 / 48_000.0).sin();
    let mut run = |c: &mut Cascade, from: usize, frames: usize| -> Vec<f32> {
        (from..from + frames)
            .map(|n| {
                let mut io = [[sine(n); 2]];
                c.process(&mut io);
                io[0][0]
            })
            .collect()
    };
    let mut out = run(&mut c, 0, 4_800);
    c.set(versatile(0.9, [0.0; 3]));
    out.extend(run(&mut c, 4_800, 24_000));
    let mut settled = Cascade::new(versatile(0.9, [0.0; 3]), 48_000);
    let reference = run(&mut settled, 0, 28_800);
    let curvature = |y: &[f32]| {
        y.windows(3)
            .map(|w| (w[2] - 2.0 * w[1] + w[0]).abs())
            .fold(0.0, f32::max)
    };
    let (spike, steady) = (curvature(&out), curvature(&reference[4_800..]));
    assert!(spike <= 1.05 * steady, "curvature {spike} against {steady}");
    let err = out[24_000..]
        .iter()
        .zip(&reference[24_000..])
        .map(|(a, b)| (a - b).abs())
        .fold(0.0, f32::max);
    assert!(err < 1e-3, "settled error {err}");
}
